            await this.userAuthPrivatePutUserDataStream(new Dictionary<string, object>() {
                { "listenKey", listenKey },
            }); // extend the expiry
        } catch(Exception error)
        {
            List<object> types = new List<object>() {"spot", "linear", "inverse"};
            for (int i = 0; i < (types?.Count ?? 0); i++)
